import math

def sigmoid(x):
    return 1 / (1 + math.exp(-x))

def neuron(acts, weights, bias):
    z = sum(a * w for a, w in zip(acts, weights)) + bias  # 가중합 + 편향
    return sigmoid(z)                                       # 0~1 로 눌러 넣기

w = [2, 2, -1, -1]
for name, a in [("획", [1, 1, 0, 0]), ("덩어리", [1, 1, 1, 1]), ("주변만", [0, 0, 1, 1])]:
    print(name, round(neuron(a, w, bias=-3), 3))
# 획 0.731 / 덩어리 0.269 / 주변만 0.007

import numpy as np

def sigmoid(z):
    return 1 / (1 + np.exp(-z))

def relu(z):
    return np.maximum(0, z)

z = np.array([-3, -0.5, 0, 0.5, 3, 10])
print(np.round(sigmoid(z), 3))  # [0.047 0.378 0.5 0.622 0.953 1.]
print(relu(z))                  # [0. 0. 0. 0.5 3. 10.]
